if(!Application.isPlaying)throw new Exception("Play required");
var t=GameObject.Find("PinballTable").transform;var ball=t.Find("Gameplay/Ball").GetComponent<Rigidbody>();var gm=GameManager.Instance;var bm=BallManager.Instance;var mode=Physics.simulationMode;var sb=new System.Text.StringBuilder();
try{Physics.simulationMode=SimulationMode.Script;foreach(int side in new[]{-1,1})foreach(float speed in new[]{5f,25f,60f}){gm.StartGame();t.GetComponentInChildren<Kickback>()?.Desarmer();gm.NotifyBallLaunched();int losses=0;Action<Rigidbody> count=b=>losses++;bm.BallDrained+=count;try{ball.position=t.TransformPoint(new Vector3(side<0?-3.825f:3.125f,.226f,5.9f));ball.linearVelocity=-t.forward*speed;ball.angularVelocity=Vector3.zero;Physics.SyncTransforms();for(int n=0;n<2000&&ball.gameObject.activeSelf;n++)Physics.Simulate(.005f);bool pass=losses==1&&gm.BallsRemaining==2&&!ball.gameObject.activeSelf;sb.AppendLine((pass?"PASS ":"FAIL ")+"outlane "+side+" speed="+speed+" losses="+losses+" remaining="+gm.BallsRemaining);}finally{bm.BallDrained-=count;}}}finally{Physics.simulationMode=mode;gm.StartGame();}
System.IO.File.WriteAllText("Tools/unity/out/reference-outlanes.txt",sb.ToString());return sb.ToString();
